CustomField.formula:
/* Base total without VAT */
(
    IF(
        Include_Technical_Fee_in_Deposit__c,
        Technical_fee__c * Deposit__c,
        0
    ) +
    (Artist_Travel_Costs__c + Performance_Fee__c) * Deposit__c
)
/* Add VAT if applicable */
* (1 + IF(VAT_Applicable__c, $Setup.VocalEventsSettings__c.VAT__c, 0))
